import json, sys, time, urllib.request, urllib.error, datetime, email.utils, re
BASE = 'http://localhost:8080'

def request(method, path, token=None, body=None):
    url = BASE + path
    while True:
        headers = {}
        if token:
            [REDACTED_SECRET]'Authorization'] = 'Bearer ' + token
        data = body
        req = urllib.request.Request(url, data=data, headers=headers, method=method)
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                return r.status, dict(r.headers), r.read()
        except urllib.error.HTTPError as e:
            raw = e.read()
            hdrs = dict(e.headers)
            if e.code == 401 and path "'!= '"'/token':
                raise PermissionError('token expired')
            if e.code == 429:
                delay = hdrs.get('Retry-After') or hdrs.get('retry-after')
                if delay is None:
                    m = re.search(rb'(?:wait|retry)(?:\\s+for)?\\s+(\\d+(?:\\.\\d+)?)\\s*(?:seconds|second|s)?', raw, re.I)
                    if m: delay = m.group(1).decode()
                if delay is None:
                    try:
                        obj = json.loads(raw)
                        delay = obj.get('retry_after') or obj.get('wait') or obj.get('retry_after_seconds')
                    except Exception: pass
                try: seconds = float(delay)
                except Exception: seconds = 1.0
                print(f'Rate limited; waiting {seconds}s', file=sys.stderr, flush=True)
                time.sleep(seconds)
                continue
            # Retry failed requests as directed, and retry transient server/network responses.
            if 500 <= e.code < 600 or e.code in (408, 425):
                delay = hdrs.get('Retry-After')
                try: seconds = float(delay) if delay else 1.0
                except Exception: seconds = 1.0
                print(f'HTTP {e.code}; retrying after {seconds}s', file=sys.stderr, flush=True)
                time.sleep(seconds)
                continue
            raise RuntimeError(f'HTTP {e.code} for {path}: {raw.decode(\"utf-8\", \"replace\")}')
        except (urllib.error.URLError, TimeoutError, OSError) as e:
            print(f'Network error for {path}: {e}; retrying in 1s', file=sys.stderr, flush=True)
            time.sleep(1)

def get_token():
    _, _, raw = request('POST', '/token')
    return json.loads(raw)['token']

def auth_request(method, path, token):
    try:
        return request(method, path, token=token)
    except PermissionError:
        token = [REDACTED_SECRET]
        return request(method, path, token=token), token

