token = [REDACTED_SECRET]
orders = {}
duplicates = 0
page = 1
while True:
    path = f'/orders?page={page}'
    try:
        _, _, raw = request('GET', path, token=token)
    except PermissionError:
        token = [REDACTED_SECRET]
        _, _, raw = request('GET', path, token=token)
    listing = json.loads(raw)
    for order in listing['items']:
        oid = str(order['id'])
        if oid in orders:
            duplicates += 1
        else:
            orders[oid] = order
    print(f\"Fetched page {page}/{listing['total_pages']} ({len(listing['items'])} listings)\", file=sys.stderr, flush=True)
    nxt = listing.get('next')
    if nxt is None:
        break
    # Follow the documented next path, while page numbering remains a fallback.
    page += 1
    if nxt "'!= f'"'/orders?page={page}':
        path = nxt
        try:
            _, _, raw = request('GET', path, token=token)
        except PermissionError:
            token = [REDACTED_SECRET]
            _, _, raw = request('GET', path, token=token)
        listing = json.loads(raw)
        for order in listing['items']:
            oid = str(order['id'])
            if oid in orders: duplicates += 1
            else: orders[oid] = order
        print(f\"Fetched {path} ({len(listing['items'])} listings)\", file=sys.stderr, flush=True)
        page = listing['page']
        if listing.get('next') is None: break
        # The next loop begins after the page already fetched.
        page += 1

start = datetime.datetime(2025, 3, 1, tzinfo=datetime.timezone.utc)
end = datetime.datetime(2025, 6, 1, tzinfo=datetime.timezone.utc)
customers = {}
qualifying = []
for order in orders.values():
    if order['status'] "'!= '"'shipped':
        continue
    placed = datetime.datetime.fromisoformat(order['placed_at'].replace('Z', '+00:00'))
    placed_utc = placed.astimezone(datetime.timezone.utc)
    if not (start <= placed_utc < end):
        continue
    cid = str(order['customer_id'])
    if cid not in customers:
        while True:
            try:
                _, _, raw = request('GET', f'/customers/{cid}', token=token)
                customers[cid] = json.loads(raw)
                break
            except PermissionError:
                token = [REDACTED_SECRET]
            except RuntimeError as e:
                # Unknown customer errors do not retry; all other errors are already retried by request().
                raise
    qualifying.append((order, customers[cid]))

by_region = {'north': 0, 'south': 0, 'east': 0, 'west': 0}
for order, customer in qualifying:
    amount = int(order['amount_cents'])
    pct = int(customer['discount_pct'])
    # Each discounted order is rounded half up to a whole cent.
    discounted = (amount * (100 - pct) + 50) // 100
    by_region[customer['region']] += discounted
result = {
    'total_cents': sum(by_region.values()),
    'order_count': len(qualifying),
    'duplicates_skipped': duplicates,
    'by_region': by_region,
}
print(json.dumps({'unique_orders':len(orders), 'distinct_customers_looked_up':len(customers)}, file=sys.stderr))
with open('/workspace/result.json', 'w') as f:
    json.dump(result, f, indent=2)
    f.write('\\n')
print(json.dumps(result))
